"""ドメインの YAML の読み込みと、検査 h (YAML の形式と、参照する名前があること)。

ディレクトリ docs/domains/ の直下のディレクトリ NN-<名前> がドメインで、その下のどの深さの .yaml も読む。
形式の SSOT はプラグインの規則の文書 (ファイル doc-structured/rules/doc-structured-domains.md)。要点:
  - 直下の domain.yaml にだけ、キー domain (説明 description) を書く
  - どのファイルにも、キー models (モデル・属性・値) と unclassified_app_terms (未分類のアプリケーション用語) を書ける
  - 英語名をマッピングのキーにし、日本語名を name_ja、定義を definition に書く
  - 属性は、ほかのモデルへの参照 refers_to (完全な ID) と、値 values を持てる
誤りは読み飛ばさず、すべて Problem (検査 h) として返す。誤りがあっても、読めた部分の定義は返す。
"""

from dataclasses import dataclass, field
from pathlib import Path
import re

from ruamel.yaml import YAMLError
from ruamel.yaml.comments import CommentedMap

from . import names, yamlio
from .names import IdError, Part
from .problems import Problem

DOMAINS_DIR = Path("docs/domains")
DOMAIN_FILE = "domain.yaml"
DOMAIN_DIR_RE = re.compile(r"^(\d{2,})-(.+)$")

TOP_KEYS = ("domain", "models", "unclassified_app_terms")
DOMAIN_KEYS = ("description",)
MODEL_KEYS = ("name_ja", "definition", "attributes")
ATTRIBUTE_KEYS = ("name_ja", "definition", "values", "refers_to")
VALUE_KEYS = ("name_ja", "definition")
TERM_KEYS = ("name_ja", "definition")
REQUIRED_KEYS = ("name_ja", "definition")
# read_yaml が、YAML として読めないファイルに返す値 (空のファイルの None と区別する)
_UNREADABLE = object()

# 日本語名に使えない文字。完全な名前を定義の行の title ("…") に書くため
NAME_JA_FORBIDDEN = ("\n", "\r", '"')

# 定義 (definition) と、ドメインの説明 (description) に使えない文字。生成したファイルは改行の CR を LF として読むので、
# CR を含む文は、生成し直した内容と一致しなくなるため
CR = "\r"


@dataclass
class Entry:
    """名前と定義を持つ 1 つの定義 (モデル・属性・値・未分類のアプリケーション用語)。"""

    id: str
    symbol: str
    name: str
    name_ja: str
    definition: str
    path: str  # 定義を書いた YAML の、リポジトリのルートからの相対パス
    line: int
    column: int
    domain: "Domain"
    parent: "Entry | None" = None
    children: list["Entry"] = field(default_factory=list)
    refers_to: str | None = None
    refers_to_line: int = 0
    refers_to_column: int = 0

    @property
    def kind_label(self) -> str:
        return names.KINDS[self.symbol].label

    def lineage(self) -> list["Entry"]:
        """親から自分までの定義 (ドメインは含まない)。"""
        chain: list[Entry] = []
        entry: Entry | None = self
        while entry is not None:
            chain.append(entry)
            entry = entry.parent
        return list(reversed(chain))

    def full_name(self) -> str:
        parts = [names.format_part("d", self.domain.name)]
        parts += [names.format_part(e.symbol, e.name_ja) for e in self.lineage()]
        return names.join_parts(parts)

    def walk(self):
        yield self
        for child in self.children:
            yield from child.walk()


@dataclass
class Domain:
    number: str
    name: str
    dir: str  # リポジトリのルートからの相対パス (docs/domains/01-loans)
    description: str = ""
    models: list[Entry] = field(default_factory=list)
    terms: list[Entry] = field(default_factory=list)  # 未分類のアプリケーション用語
    yaml_files: list[str] = field(default_factory=list)

    @property
    def id(self) -> str:
        return names.build_id([Part("d", self.name)])

    def full_name(self) -> str:
        return names.format_part("d", self.name)

    def entries(self):
        """モデル (その属性と値を含む) と未分類のアプリケーション用語を、定義の並び順に返す。"""
        for model in self.models:
            yield from model.walk()
        yield from self.terms


@dataclass
class Project:
    root: Path
    domains: list[Domain] = field(default_factory=list)
    entries: dict[str, Entry] = field(default_factory=dict)


def rel(root: Path, path: Path) -> str:
    return path.relative_to(root).as_posix()


class _Loader:
    def __init__(self, root: Path):
        self.root = root
        self.problems: list[Problem] = []
        self.project = Project(root=root)

    def problem(self, path: str, message: str, line: int | None = None, column: int | None = None) -> None:
        self.problems.append(Problem("h", path, message, line, column))

    def load(self) -> None:
        domains_dir = self.root / DOMAINS_DIR
        if not domains_dir.is_dir():
            return
        numbers: dict[str, str] = {}
        domain_names: dict[str, str] = {}
        for child in sorted(domains_dir.iterdir(), key=lambda p: p.name):
            if child.name.startswith(".") or not child.is_dir():
                continue
            child_rel = rel(self.root, child)
            match = DOMAIN_DIR_RE.match(child.name)
            if not match or not names.is_name(match.group(2)):
                self.problem(
                    child_rel,
                    f"ドメインのディレクトリ名 {child.name} は、NN-<名前> の形でなければならない "
                    "(NN は 2 桁以上の数字、名前は snake_case)",
                )
                continue
            number, name = match.group(1), match.group(2)
            if number in numbers:
                self.problem(child_rel, f"ドメインの番号 {number} は、{numbers[number]} と同じ")
                continue
            if name in domain_names:
                self.problem(child_rel, f"ドメインの名前 {name} は、{domain_names[name]} と同じ")
                continue
            numbers[number] = child_rel
            domain_names[name] = child_rel
            domain = Domain(number=number, name=name, dir=child_rel)
            self.project.domains.append(domain)
            self.load_domain(domain, child)
        self.resolve_references()

    def yaml_files(self, domain: Domain, directory: Path) -> list[Path]:
        """ドメインのディレクトリの下の YAML を、直下の domain.yaml を先にし、残りはパスの文字コードの順に返す。"""
        found: list[Path] = []
        for path in sorted(directory.rglob("*")):
            relative = path.relative_to(directory)
            if any(part.startswith(".") for part in relative.parts) or not path.is_file():
                continue
            if path.suffix == ".yml":
                self.problem(rel(self.root, path), "拡張子は .yaml にする (.yml のファイルは読まない)")
            elif path.suffix == ".yaml":
                found.append(path)
        found.sort(key=lambda p: (p != directory / DOMAIN_FILE, p.relative_to(directory).as_posix()))
        return found

    def load_domain(self, domain: Domain, directory: Path) -> None:
        files = self.yaml_files(domain, directory)
        root_file = directory / DOMAIN_FILE
        if root_file not in files:
            self.problem(domain.dir, f"ドメインのディレクトリの直下に {DOMAIN_FILE} が無い")
        model_names: dict[str, Entry] = {}
        term_names: dict[str, Entry] = {}
        for path in files:
            path_rel = rel(self.root, path)
            domain.yaml_files.append(path_rel)
            data = self.read_yaml(path, path_rel)
            if data is _UNREADABLE:
                # 読めないファイルは、キー domain があるかどうかが分からないので、無いとは報告しない
                continue
            if data is None:
                if path == root_file:
                    self.problem(path_rel, "キー domain (ドメインの説明) が無い")
                continue
            for key in data:
                line, column = _key_position(data, key)
                if key == "domain":
                    if path != root_file:
                        self.problem(
                            path_rel, "キー domain は、ドメインのディレクトリの直下の domain.yaml にだけ書ける", line, column
                        )
                        continue
                    self.load_domain_description(domain, data, path_rel)
                elif key == "models":
                    self.load_models(domain, data, path_rel, model_names)
                elif key == "unclassified_app_terms":
                    self.load_terms(domain, data, path_rel, term_names)
                else:
                    self.unknown_key(path_rel, key, TOP_KEYS, line, column)
            if path == root_file and "domain" not in data:
                self.problem(path_rel, "キー domain (ドメインの説明) が無い", 1, 1)

    def read_yaml(self, path: Path, path_rel: str) -> CommentedMap | None | object:
        """YAML を読む。空のファイルは None、読めないファイルは問題を報告して _UNREADABLE を返す。"""
        try:
            data = yamlio.load(path.read_text(encoding="utf-8"))
        except YAMLError as e:
            mark = getattr(e, "problem_mark", None) or getattr(e, "context_mark", None)
            reason = getattr(e, "problem", None) or str(e)
            if mark is not None:
                self.problem(path_rel, f"YAML として読めない: {reason}", mark.line + 1, mark.column + 1)
            else:
                self.problem(path_rel, f"YAML として読めない: {reason}")
            return _UNREADABLE
        if data is None:
            return None
        if not isinstance(data, CommentedMap):
            self.problem(path_rel, "ファイルの全体は、キーと値のマッピングでなければならない", 1, 1)
            return _UNREADABLE
        return data

    def unknown_key(self, path_rel: str, key, allowed: tuple[str, ...], line: int, column: int) -> None:
        self.problem(path_rel, f"知らないキー {key} (書けるキー: {', '.join(allowed)})", line, column)

    def mapping_of(self, parent: CommentedMap, key: str, path_rel: str) -> CommentedMap | None:
        value = parent[key]
        if not isinstance(value, CommentedMap):
            line, column = _value_position(parent, key)
            self.problem(path_rel, f"{key} の値は、キーと値のマッピングでなければならない", line, column)
            return None
        return value

    def load_domain_description(self, domain: Domain, data: CommentedMap, path_rel: str) -> None:
        mapping = self.mapping_of(data, "domain", path_rel)
        if mapping is None:
            return
        for key in mapping:
            if key not in DOMAIN_KEYS:
                self.unknown_key(path_rel, key, DOMAIN_KEYS, *_key_position(mapping, key))
        line, column = _key_position(data, "domain")
        description = self.without_cr(
            mapping, "description", self.text(mapping, "description", path_rel, line, column, "domain"), path_rel, "domain"
        )
        if description is not None:
            domain.description = description

    def text(self, mapping: CommentedMap, key: str, path_rel: str, line: int, column: int, owner: str) -> str | None:
        """必須の文字列の項目を読む。無い・文字列でない・空なら問題を足して None を返す。"""
        if key not in mapping:
            self.problem(path_rel, f"{owner} に必須の項目 {key} が無い", line, column)
            return None
        value = mapping[key]
        vline, vcolumn = _value_position(mapping, key)
        if not isinstance(value, str) or not value.strip():
            self.problem(path_rel, f"{owner} の {key} は、空でない文字列でなければならない", vline, vcolumn)
            return None
        return value.strip()

    def without_cr(self, mapping: CommentedMap, key: str, value: str | None, path_rel: str, owner: str) -> str | None:
        """関数 text で読んだ値に CR があれば、問題を足して None を返す。"""
        if value is not None and CR in value:
            self.problem(path_rel, f"{owner} の {key} に、CR は使えない", *_value_position(mapping, key))
            return None
        return value

    def entry(
        self,
        domain: Domain,
        parent_map: CommentedMap,
        name,
        symbol: str,
        allowed: tuple[str, ...],
        path_rel: str,
        parent: Entry | None,
    ) -> tuple[Entry | None, CommentedMap | None]:
        """1 つの定義を読む。名前・項目・日本語名を検査する。"""
        line, column = _key_position(parent_map, name)
        label = names.KINDS[symbol].label
        if not isinstance(name, str) or not names.is_name(name):
            self.problem(path_rel, f"{label}の名前 {name} が snake_case でない", line, column)
            return None, None
        mapping = parent_map[name]
        if not isinstance(mapping, CommentedMap):
            self.problem(path_rel, f"{label} {name} の値は、キーと値のマッピングでなければならない", line, column)
            return None, None
        for key in mapping:
            if key not in allowed:
                self.unknown_key(path_rel, key, allowed, *_key_position(mapping, key))
        owner = f"{label} {name}"
        name_ja = self.text(mapping, "name_ja", path_rel, line, column, owner)
        definition = self.without_cr(
            mapping, "definition", self.text(mapping, "definition", path_rel, line, column, owner), path_rel, owner
        )
        if name_ja is not None and any(ch in name_ja for ch in NAME_JA_FORBIDDEN):
            self.problem(
                path_rel, f'{owner} の name_ja に、改行と " は使えない', *_value_position(mapping, "name_ja")
            )
            name_ja = None
        parent_parts = names.parse_id(parent.id) if parent else [Part("d", domain.name)]
        entry = Entry(
            id=names.build_id([*parent_parts, Part(symbol, name)]),
            symbol=symbol,
            name=name,
            name_ja=name_ja or name,
            definition=definition or "",
            path=path_rel,
            line=line,
            column=column,
            domain=domain,
            parent=parent,
        )
        if parent is not None:
            parent.children.append(entry)
        return entry, mapping

    def load_models(self, domain: Domain, data: CommentedMap, path_rel: str, seen: dict[str, Entry]) -> None:
        models = self.mapping_of(data, "models", path_rel)
        if models is None:
            return
        for name in models:
            model, mapping = self.entry(domain, models, name, "m", MODEL_KEYS, path_rel, None)
            if model is None:
                continue
            if name in seen:
                other = seen[name]
                self.problem(
                    path_rel, f"モデル {name} は、{other.path}:{other.line} にもある", model.line, model.column
                )
                continue
            seen[name] = model
            domain.models.append(model)
            if "attributes" in mapping:
                self.load_attributes(domain, model, mapping, path_rel)

    def load_attributes(self, domain: Domain, model: Entry, model_map: CommentedMap, path_rel: str) -> None:
        attributes = self.mapping_of(model_map, "attributes", path_rel)
        if attributes is None:
            return
        for name in attributes:
            attribute, mapping = self.entry(domain, attributes, name, "a", ATTRIBUTE_KEYS, path_rel, model)
            if attribute is None:
                continue
            if "refers_to" in mapping:
                value = mapping["refers_to"]
                vline, vcolumn = _value_position(mapping, "refers_to")
                if isinstance(value, str) and value.strip():
                    attribute.refers_to = value.strip()
                    attribute.refers_to_line, attribute.refers_to_column = vline, vcolumn
                else:
                    self.problem(path_rel, f"属性 {name} の refers_to は、モデルの ID の文字列でなければならない", vline, vcolumn)
            if "values" in mapping:
                values = self.mapping_of(mapping, "values", path_rel)
                if values is None:
                    continue
                for value_name in values:
                    self.entry(domain, values, value_name, "v", VALUE_KEYS, path_rel, attribute)

    def load_terms(self, domain: Domain, data: CommentedMap, path_rel: str, seen: dict[str, Entry]) -> None:
        terms = self.mapping_of(data, "unclassified_app_terms", path_rel)
        if terms is None:
            return
        for name in terms:
            term, _ = self.entry(domain, terms, name, "ut", TERM_KEYS, path_rel, None)
            if term is None:
                continue
            if name in seen:
                other = seen[name]
                self.problem(
                    path_rel,
                    f"未分類のアプリケーション用語 {name} は、{other.path}:{other.line} にもある",
                    term.line,
                    term.column,
                )
                continue
            seen[name] = term
            domain.terms.append(term)

    def resolve_references(self) -> None:
        entries = self.project.entries
        for domain in self.project.domains:
            for entry in domain.entries():
                entries[entry.id] = entry
        for domain in self.project.domains:
            for entry in domain.entries():
                if entry.refers_to is None:
                    continue
                where = (entry.path, entry.refers_to_line, entry.refers_to_column)
                try:
                    kind = names.kind_of(entry.refers_to)
                except IdError as e:
                    self.problem(where[0], f"refers_to の値が ID の形でない: {e}", *where[1:])
                    continue
                if kind != "m":
                    self.problem(where[0], f"refers_to の参照先 {entry.refers_to} はモデルでない (参照できるのはモデルだけ)", *where[1:])
                elif entry.refers_to not in entries:
                    self.problem(where[0], f"refers_to の参照先 {entry.refers_to} が無い", *where[1:])


def _key_position(mapping: CommentedMap, key) -> tuple[int, int]:
    line, column = mapping.lc.key(key)
    return line + 1, column + 1


def _value_position(mapping: CommentedMap, key) -> tuple[int, int]:
    line, column = mapping.lc.value(key)
    return line + 1, column + 1


def load_project(root: Path) -> tuple[Project, list[Problem]]:
    """リポジトリのルートからドメインの YAML を読む。検査 h の問題も返す。"""
    loader = _Loader(root)
    loader.load()
    return loader.project, loader.problems
"""ID と、限定付きの名前。

ID は、種類の記号と名前 (snake_case) をハイフンで交互につなぎ、親から子の順に並べたもの
(例 d-loans-m-loan-a-status-v-on_loan)。ファイルの ID は、親の ID にファイルの種類の記号を足したもの
(例 d-loans-models)。ファイルの種類の記号は名前を取らない。
手書きのファイル (concept・design・problem) の下には、節 (記号 h) と子のファイル (記号 f) の ID を作る
(例 d-loans-concept-h-return_deadline・d-push-design-f-device_operations)。子のファイルの下には節だけを作る。

限定付きの名前は、親から順に「種類 + 名前」を「の」でつないだもの。ユーザーレベルの種類は日本語名をかぎ括弧で、
開発レベルの種類は英語名をコードの書式で書く。名前の形の表の SSOT はプラグインの規則の文書
(ファイル doc-structured/rules/doc-structured-docs.md)。このモジュールの表 KINDS と FILE_KINDS が規則の文書の表と
同じであることは、テスト tests/test_rules_docs.py が検査する。
"""

import re
from dataclasses import dataclass

# 名前 (英語名) の形。英小文字で始まり、英小文字・数字を 1 つの「_」で区切る
NAME_RE = re.compile(r"^[a-z][a-z0-9]*(_[a-z0-9]+)*$")


@dataclass(frozen=True)
class Kind:
    """名前を持つ種類。"""

    symbol: str
    label: str  # 種類の名前 (限定付きの名前と文書に書く)
    user_level: bool  # True なら日本語名をかぎ括弧で、False なら英語名をコードの書式で書く
    parents: tuple[str, ...]  # 親になれる種類の記号。空ならいちばん上の種類


# この版のツールが扱う種類。後の sub-issue で種類を足す
KINDS: dict[str, Kind] = {
    k.symbol: k
    for k in (
        Kind("d", "ドメイン", False, ()),
        Kind("m", "モデル", True, ("d",)),
        Kind("a", "属性", True, ("m",)),
        Kind("v", "値", True, ("a",)),
        Kind("ut", "未分類のアプリケーション用語", True, ("d",)),
    )
}

# 生成するファイルの種類の記号と、そのファイル名。親はドメイン
FILE_KINDS: dict[str, str] = {
    "models": "models.md",
    "terms": "terms.md",
    "unclassified_app_terms": "unclassified_app_terms.md",
}
# 手書きのファイルの種類の記号と、そのファイル名。親はドメイン。ドメインの README.md の表に、この順に載せる
HANDWRITTEN_FILE_KINDS: dict[str, str] = {
    "concept": "concept.md",
    "problem": "problem.md",
    "design": "design.md",
}
FILE_KIND_LABEL = "ファイル"

# 種類の名前の略称。本文の最初の箇所では、略称で書いた形も書ける (完全な名前には正式名称を書く)
ABBREVIATIONS: dict[str, str] = {"ut": "未分類の用語"}

# 手書きのファイルの節。名前は書く人が決める snake_case で、限定付きの名前には見出しの文を書く
SECTION = Kind("h", "節", True, ())
# 手書きのファイルの子のファイル (100 行を超えたファイルを分けた先)。限定付きの名前には、ドメインのディレクトリからのパスを書く
CHILD_FILE_SYMBOL = "f"


class IdError(ValueError):
    """ID の形が違う。メッセージは利用者に見せる文。"""


@dataclass(frozen=True)
class Part:
    """ID の 1 つの部分。name が None なら、ファイルの種類の記号。"""

    symbol: str
    name: str | None


def is_name(text: str) -> bool:
    return bool(NAME_RE.match(text))


def build_id(parts: list[Part]) -> str:
    tokens: list[str] = []
    for part in parts:
        tokens.append(part.symbol)
        if part.name is not None:
            tokens.append(part.name)
    return "-".join(tokens)


def parse_id(text: str) -> list[Part]:
    """ID を部分に分ける。種類の記号・名前の形・親子の組み合わせが違えば IdError。"""
    tokens = text.split("-")
    parts: list[Part] = []
    i = 0
    while i < len(tokens):
        symbol = tokens[i]
        parent = parts[-1].symbol if parts else None
        if symbol in KINDS or symbol in (SECTION.symbol, CHILD_FILE_SYMBOL):
            if symbol in KINDS:
                kind = KINDS[symbol]
                allowed = (parent is None and not kind.parents) or (parent is not None and parent in kind.parents)
            elif symbol == SECTION.symbol:
                allowed = parent in HANDWRITTEN_FILE_KINDS or parent == CHILD_FILE_SYMBOL
            else:
                allowed = parent in HANDWRITTEN_FILE_KINDS
            if not allowed:
                raise IdError(f"ID {text} の {symbol} は、{parent or '先頭'} の後に書けない")
            if i + 1 >= len(tokens):
                raise IdError(f"ID {text} の {symbol} の後に名前が無い")
            name = tokens[i + 1]
            if not is_name(name):
                raise IdError(f"ID {text} の名前 {name} が snake_case でない")
            parts.append(Part(symbol, name))
            i += 2
        elif symbol in FILE_KINDS:
            if parent != "d" or i + 1 != len(tokens):
                raise IdError(f"ID {text} のファイルの種類 {symbol} は、ドメインの直後の最後にだけ書ける")
            parts.append(Part(symbol, None))
            i += 1
        elif symbol in HANDWRITTEN_FILE_KINDS:
            if parent != "d":
                raise IdError(f"ID {text} のファイルの種類 {symbol} は、ドメインの直後にだけ書ける")
            parts.append(Part(symbol, None))
            i += 1
        else:
            raise IdError(f"ID {text} に知らない種類の記号 {symbol} がある")
    if not parts:
        raise IdError(f"ID {text!r} が空")
    return parts


def kind_of(text: str) -> str:
    """ID の最後の種類の記号。"""
    return parse_id(text)[-1].symbol


def format_part(symbol: str, display: str, abbreviated: bool = False) -> str:
    """「種類 + 名前」の 1 つ。display は、ユーザーレベルなら日本語名、開発レベルなら英語名、ファイルならファイル名、
    子のファイルならドメインのディレクトリからのパス、節なら見出しの文。
    abbreviated が True なら、種類の名前を略称 (ABBREVIATIONS) で書く。略称の無い種類は、正式名称で書く。"""
    if symbol in FILE_KINDS or symbol in HANDWRITTEN_FILE_KINDS or symbol == CHILD_FILE_SYMBOL:
        return f"{FILE_KIND_LABEL} `{display}`"
    if symbol == SECTION.symbol:
        return f"{SECTION.label}「{display}」"
    kind = KINDS[symbol]
    label = ABBREVIATIONS.get(symbol, kind.label) if abbreviated else kind.label
    if kind.user_level:
        return f"{label}「{display}」"
    return f"{label} `{display}`"


def join_parts(formatted: list[str]) -> str:
    """「種類 + 名前」を親から順に「の」でつなぐ。コードの書式の後には空白を 1 つ入れる (「ドメイン `loans` のモデル」)。"""
    result = ""
    for i, text in enumerate(formatted):
        if i > 0:
            result += " の" if result.endswith("`") else "の"
        result += text
    return result

"""ドメインの YAML から、人が読む Markdown を生成する。

ドメインのディレクトリの直下に README.md・models.md・unclassified_app_terms.md・terms.md を、全体の用語の索引
docs/glossary.md を生成する。生成するファイルの中身の SSOT はプラグインの規則の文書
(ファイル doc-structured/rules/doc-structured-domains.md)。要点:
  - 先頭に、生成したファイルの先頭の記述 (モジュール generated_header) を書く
  - 定義ごとに <a name="ID"></a> と見出しを書く。見出しは「種類 + 日本語名」の後に英語名をコードの書式で書く
  - リンクは reference-style で、ラベルを ID にし、定義の行 [ID]: 相対パス#ID "完全な名前" をファイルの末尾に書く
  - 用語の索引は定義の文を持たず、日本語名の文字コードの順 (同じなら ID の順) に、定義へのリンクを並べる
  - 定義が 1 つも無い種類のファイルは作らない
  - README.md の表には、ドメインのディレクトリの直下にある手書きのファイルを先に、生成したファイルを後に並べる
  - docs/.gitattributes に、生成したファイル (docs/.gitattributes 自身を含む) の merge の設定を書く
  - 生成するファイルの場所に、先頭の記述が無く、空白と BOM 以外の文字があるファイル (手で書いたファイル) があれば、何も書かない (呼び出し元がエラーにする)
同じ入力からは、いつも同じ出力を作る (時刻や環境に依存する値を書かない)。
"""

import posixpath
from pathlib import Path

from . import generated_header, names
from .domains import DOMAINS_DIR, Domain, Entry, Project

GLOSSARY_PATH = "docs/glossary.md"
GITATTRIBUTES_PATH = "docs/.gitattributes"
# 生成したファイルの merge の設定。git の組み込みの merge driver binary は、競合したときに git が ours とする側の内容を残し、
# 競合のマークを入れない (ファイルは競合の状態のまま)。どの側が ours になるかは git のコマンドによって違い、
# 残った内容は古いことがあるので、生成し直してから git add する
GITATTRIBUTES_COMMENT = (
    "# 生成したファイルが競合したときは、git が ours とする側の内容が残る (組み込みの merge driver binary。"
    "どの側が ours になるかは git のコマンドによって違う)。生成し直してから git add する"
)
README = "README.md"
FILE_DESCRIPTIONS = {
    "concept": "概念・境界・不変条件・方針・理由",
    "problem": "問題",
    "design": "設計の判断と短い理由",
    "models": "モデル・属性・値の定義",
    "unclassified_app_terms": "未分類のアプリケーション用語の定義",
    "terms": "このドメインの用語の索引",
}
# 見出しの深さ。モデル 2・属性 3・値 4。未分類のアプリケーション用語は 2
HEADING_LEVELS = {"m": 2, "a": 3, "v": 4, "ut": 2}


def escape_link_text(text: str) -> str:
    return text.replace("\\", "\\\\").replace("[", "\\[").replace("]", "\\]")


def escape_cell(text: str) -> str:
    return text.replace("|", "\\|")


class _Links:
    """1 つのファイルの reference-style のリンクと、末尾に書く定義の行。"""

    def __init__(self, file: str):
        self.file = file
        self.definitions: dict[str, tuple[str, str]] = {}

    def link(self, text: str, target_id: str, target_file: str, title: str) -> str:
        if target_file == self.file:
            href = f"#{target_id}"
        else:
            relative = posixpath.relpath(target_file, posixpath.dirname(self.file))
            href = f"{relative}#{target_id}"
        self.definitions[target_id] = (href, title)
        return f"[{escape_link_text(text)}][{target_id}]"

    def lines(self) -> list[str]:
        return [f'[{label}]: {href} "{title}"' for label, (href, title) in sorted(self.definitions.items())]


def _file_name(symbol: str) -> str:
    return names.FILE_KINDS.get(symbol) or names.HANDWRITTEN_FILE_KINDS[symbol]


def file_path(domain: Domain, symbol: str) -> str:
    return f"{domain.dir}/{_file_name(symbol)}"


def _file_id(domain: Domain, symbol: str) -> str:
    return names.build_id([names.Part("d", domain.name), names.Part(symbol, None)])


def _file_title(domain: Domain, symbol: str) -> str:
    return names.join_parts([domain.full_name(), names.format_part(symbol, _file_name(symbol))])


def entry_file(entry: Entry) -> str:
    symbol = "unclassified_app_terms" if entry.symbol == "ut" else "models"
    return file_path(entry.domain, symbol)


def _entry_link(links: _Links, entry: Entry, text: str) -> str:
    return links.link(text, entry.id, entry_file(entry), entry.full_name())


def _reference_text(entry: Entry, from_domain: Domain) -> str:
    """ほかの定義を指すリンクの表示の文。同じドメインなら「種類 + 名前」、ほかのドメインなら完全な名前。"""
    if entry.domain is from_domain:
        return names.format_part(entry.symbol, entry.name_ja)
    return entry.full_name()


def _document(source: str, anchor: str | None, blocks: list[str], links: _Links) -> str:
    parts = [generated_header.markdown_line(source)]
    if anchor:
        parts.append(f'<a name="{anchor}"></a>')
    text = "\n".join(parts) + "\n\n" + "\n\n".join(blocks)
    definition_lines = links.lines()
    if definition_lines:
        text += "\n\n" + "\n".join(definition_lines)
    return text + "\n"


def _definition_block(entry: Entry, extra: str = "") -> str:
    heading = "#" * HEADING_LEVELS[entry.symbol]
    title = f"{names.format_part(entry.symbol, entry.name_ja)} `{entry.name}`"
    body = entry.definition
    if extra:
        body += extra if body.endswith("。") else f" {extra}"
    return f'<a name="{entry.id}"></a>\n\n{heading} {title}\n\n{body}'


def _referencing_models(project: Project) -> dict[str, list[Entry]]:
    """モデルの ID から、そのモデルを参照するモデルへの対応。定義の並び順で、重複は除く。"""
    result: dict[str, list[Entry]] = {}
    for domain in project.domains:
        for model in domain.models:
            for attribute in model.children:
                target = attribute.refers_to
                if target in project.entries and model not in result.setdefault(target, []):
                    result[target].append(model)
    return result


def render_models(project: Project, domain: Domain, referencing: dict[str, list[Entry]]) -> str:
    path = file_path(domain, "models")
    links = _Links(path)
    blocks = [f"# {domain.full_name()} のモデル"]
    for model in domain.models:
        blocks.append(_definition_block(model))
        users = referencing.get(model.id, [])
        if users:
            listed = "・".join(_entry_link(links, m, _reference_text(m, domain)) for m in users)
            blocks.append(f"このモデルを参照するモデル: {listed}")
        for attribute in model.children:
            extra = ""
            if attribute.refers_to in project.entries:
                target = project.entries[attribute.refers_to]
                extra = "参照先: " + _entry_link(links, target, _reference_text(target, domain))
            blocks.append(_definition_block(attribute, extra))
            for value in attribute.children:
                blocks.append(_definition_block(value))
    return _document(f"{domain.dir}/", _file_id(domain, "models"), blocks, links)


def render_unclassified_app_terms(domain: Domain) -> str:
    path = file_path(domain, "unclassified_app_terms")
    links = _Links(path)
    blocks = [f"# {domain.full_name()} の{names.KINDS['ut'].label}"]
    blocks += [_definition_block(term) for term in domain.terms]
    return _document(f"{domain.dir}/", _file_id(domain, "unclassified_app_terms"), blocks, links)


def _kind_text(entry: Entry) -> str:
    """用語の索引の「種類」の列。ドメインの中の親の「種類 + 名前」と、自分の種類の名前。"""
    parents = [names.format_part(e.symbol, e.name_ja) for e in entry.lineage()[:-1]]
    return names.join_parts([*parents, entry.kind_label])


def _sorted_terms(entries: list[Entry]) -> list[Entry]:
    return sorted(entries, key=lambda e: (e.name_ja, e.id))


def render_terms(domain: Domain) -> str:
    path = file_path(domain, "terms")
    links = _Links(path)
    rows = ["| 用語 | 種類 | 英語名 |", "|---|---|---|"]
    for entry in _sorted_terms(list(domain.entries())):
        term = escape_cell(_entry_link(links, entry, entry.name_ja))
        rows.append(f"| {term} | {escape_cell(_kind_text(entry))} | `{entry.name}` |")
    blocks = [f"# {domain.full_name()} の用語の索引", "\n".join(rows)]
    return _document(f"{domain.dir}/", _file_id(domain, "terms"), blocks, links)


def render_glossary(project: Project) -> str:
    links = _Links(GLOSSARY_PATH)
    rows = ["| 用語 | 種類 | 英語名 | ドメイン |", "|---|---|---|---|"]
    all_entries = [e for d in project.domains for e in d.entries()]
    for entry in _sorted_terms(all_entries):
        domain = entry.domain
        term = escape_cell(_entry_link(links, entry, entry.name_ja))
        domain_link = links.link(f"`{domain.name}`", domain.id, f"{domain.dir}/{README}", domain.full_name())
        rows.append(f"| {term} | {escape_cell(_kind_text(entry))} | `{entry.name}` | {domain_link} |")
    blocks = ["# 用語の索引", "\n".join(rows)]
    return _document(f"{DOMAINS_DIR.as_posix()}/", None, blocks, links)


def render_readme(domain: Domain, files: list[str]) -> str:
    """files は、表に載せるファイルの種類の記号。ドメインのディレクトリの直下にある手書きのファイル (concept・problem・design)
    を先に、このドメインで生成するファイル (models・unclassified_app_terms・terms) を後に並べる。"""
    path = f"{domain.dir}/{README}"
    links = _Links(path)
    blocks = [f"# {domain.full_name()}"]
    if domain.description:
        blocks.append(domain.description)
    if files:
        rows = ["| 文書 | 中身 |", "|---|---|"]
        for symbol in files:
            link = links.link(
                f"`{_file_name(symbol)}`", _file_id(domain, symbol), file_path(domain, symbol),
                _file_title(domain, symbol),
            )
            rows.append(f"| {link} | {FILE_DESCRIPTIONS[symbol]} |")
        blocks.append("\n".join(rows))
    return _document(f"{domain.dir}/", domain.id, blocks, links)


def render_gitattributes(paths: list[str]) -> str:
    """paths は、ディレクトリ docs/ の下の生成するファイルの、リポジトリのルートからの相対パス (docs/.gitattributes を除く)。"""
    base = posixpath.dirname(GITATTRIBUTES_PATH)
    lines = [generated_header.hash_line(f"{DOMAINS_DIR.as_posix()}/"), GITATTRIBUTES_COMMENT]
    for path in sorted([*paths, GITATTRIBUTES_PATH]):
        if not path.startswith(f"{base}/"):
            raise ValueError(f"ディレクトリ {base}/ の外のファイルは {GITATTRIBUTES_PATH} に書けない: {path}")
        lines.append(f"/{posixpath.relpath(path, base)} merge=binary")
    return "\n".join(lines) + "\n"


def render_project(project: Project) -> dict[str, str]:
    """生成するファイルの、リポジトリのルートからの相対パスと内容。"""
    outputs: dict[str, str] = {}
    referencing = _referencing_models(project)
    for domain in project.domains:
        # 手書きのファイルは、今あるものを表に載せる (足したり消したりすると、検査 a が README.md の生成し直しを求める)
        files = [s for s in names.HANDWRITTEN_FILE_KINDS if (project.root / file_path(domain, s)).is_file()]
        if domain.models:
            outputs[file_path(domain, "models")] = render_models(project, domain, referencing)
            files.append("models")
        if domain.terms:
            outputs[file_path(domain, "unclassified_app_terms")] = render_unclassified_app_terms(domain)
            files.append("unclassified_app_terms")
        if domain.models or domain.terms:
            outputs[file_path(domain, "terms")] = render_terms(domain)
            files.append("terms")
        outputs[f"{domain.dir}/{README}"] = render_readme(domain, files)
    if any(d.models or d.terms for d in project.domains):
        outputs[GLOSSARY_PATH] = render_glossary(project)
    if outputs:
        outputs[GITATTRIBUTES_PATH] = render_gitattributes(list(outputs))
    return dict(sorted(outputs.items()))


def generated_files(root: Path) -> dict[str, generated_header.Header]:
    """ディレクトリ docs/ の下の、先頭の記述を持つファイル (生成したファイル) と、その記述。

    調べるのは、拡張子が .md と .yaml のファイルと、名前が .gitattributes のファイル。
    """
    found: dict[str, generated_header.Header] = {}
    docs = root / "docs"
    if not docs.is_dir():
        return found
    for path in sorted(docs.rglob("*")):
        if not path.is_file() or (path.suffix not in (".md", ".yaml") and path.name != ".gitattributes"):
            continue
        header = generated_header.read_file_header(path)
        if header is not None:
            found[path.relative_to(root).as_posix()] = header
    return found


HANDWRITTEN_MESSAGE = "手で書いたファイルが、生成するファイルの場所にある"


def is_handwritten(content: generated_header.FileContent) -> bool:
    """generated_header.read_file で読んだファイルが、手で書いたファイルか。

    先頭の記述が無く、空白と BOM (U+FEFF) 以外の文字があるファイルを、手で書いたファイルとする。
    空のファイルと、空白と BOM だけのファイル (生成したファイルが中身ごと消えたものなど) は、失う内容が無いので含めない。
    """
    return content.header is None and not content.is_blank


class HandwrittenFilesError(Exception):
    """生成するファイルの場所に手で書いたファイルがあるので、何も書かなかったことを表す。"""

    def __init__(self, paths: list[str]):
        super().__init__(f"{HANDWRITTEN_MESSAGE}: {', '.join(paths)}")
        self.paths = paths


def handwritten_fix(relative: str) -> str:
    """手で書いたファイルが生成するファイルの場所にあるときの直し方。"""
    if relative == GITATTRIBUTES_PATH:
        return (
            "手で書いた行を、パターンをリポジトリのルートからの相対に書き換えて (docs/.gitattributes のパターンは docs/ からの相対)、"
            "リポジトリのルートの .gitattributes に移してから、このファイルを消す"
        )
    return "ファイルの名前を変える。または、内容を手書きの文書に移してから、このファイルを消す"


def write_outputs(root: Path, outputs: dict[str, str]) -> tuple[list[str], list[str]]:
    """生成したファイルを書き、生成し直すと無くなるファイルを消す。書いたファイルと消したファイルを返す。

    消すのは、先頭の記述を持つファイル (生成したファイル) だけ。手書きのファイルは消さない。
    内容が同じファイルは書かない。生成するファイルの場所に手で書いたファイルがあれば、何も書かずに
    HandwrittenFilesError を送出する (呼び出し元が、そのパスの配列から利用者にエラーを伝える)。
    """
    # 生成するファイルの場所にある今のファイルを 1 回だけ読み、手で書いたファイルの判定と書く前の比較の両方に使う
    existing = {
        relative: generated_header.read_file(root / relative) for relative in outputs if (root / relative).is_file()
    }
    handwritten = [relative for relative, current in existing.items() if is_handwritten(current)]
    if handwritten:
        raise HandwrittenFilesError(handwritten)
    written: list[str] = []
    for relative, content in outputs.items():
        path = root / relative
        # 検査 a と同じ判定で比べる (改行の違いだけなら書かず、BOM や UTF-8 として読めないバイトがあれば上書きする)
        if relative in existing and existing[relative].matches(content):
            continue
        path.parent.mkdir(parents=True, exist_ok=True)
        with path.open("w", encoding="utf-8", newline="\n") as f:
            f.write(content)
        written.append(relative)
    deleted: list[str] = []
    for relative in generated_files(root):
        if relative not in outputs:
            (root / relative).unlink()
            deleted.append(relative)
    return written, deleted
"""サブコマンド check が実行する検査と、検査 a (生成し直して差分が無い)。

検査の群 (決定の一覧の問 12 (3)):
  軽い群 (--light。デフォルト)  文書と YAML だけで実行できる検査。この版では a・b・c-2・h・i・k
  重い群 (--heavy)              データベースなどが要る検査。この版には無い
--all は両方、--only <検査> は 1 つだけを実行する。
検査 h (YAML の形式) に誤りがあると、定義の一覧と完全な名前が正しく作れないので、検査 a・b・i は実行せず、そのことを報告する。
検査 c-2 も、検査 b が確認するリンクの上で数えるので、検査 b と同じく実行しない (決めた経緯は Issue #198 のコメントの 6)。
検査 k (手書きの Markdown の行数) は YAML を使わないので、いつも実行する。
"""

import difflib
from dataclasses import dataclass, field
from pathlib import Path

from . import generated_header
from .cycles import check_cycles
from .direction import check_direction, check_markdown_direction
from .documents import load_documents
from .domains import Project, load_project
from .generate import GITATTRIBUTES_PATH, HANDWRITTEN_MESSAGE, generated_files, handwritten_fix, is_handwritten, render_project
from .length import check_length
from .links import check_links
from .problems import Problem

LIGHT = ("a", "b", "c-2", "h", "i", "k")
HEAVY: tuple[str, ...] = ()
ALL = LIGHT + HEAVY


@dataclass
class CheckResult:
    checks: tuple[str, ...]  # 実行するよう指定された検査
    problems: list[Problem] = field(default_factory=list)
    skipped: list[str] = field(default_factory=list)  # 検査 h の誤りのため実行しなかった検査

    @property
    def ok(self) -> bool:
        return not self.problems and not self.skipped


def check_generated(root: Path, project: Project) -> list[Problem]:
    """検査 a: 生成し直した内容と、今のファイルを比べる。"""
    problems: list[Problem] = []
    outputs = render_project(project)
    for relative, expected in outputs.items():
        header = generated_header.read_header(expected)
        if relative == GITATTRIBUTES_PATH:
            how = f"このファイルを直接編集せず、{header.command} を実行する。{generated_header.GITATTRIBUTES_GUIDE}"
        else:
            how = f"このファイルを直接編集せず、生成元 {header.source} の YAML を直して {header.command} を実行する"
        path = root / relative
        if not path.is_file():
            problems.append(Problem("a", relative, f"生成するはずのファイルが無い。{header.command} を実行する"))
            continue
        content = generated_header.read_file(path)
        if is_handwritten(content):
            problems.append(Problem("a", relative, f"{HANDWRITTEN_MESSAGE}。{handwritten_fix(relative)}"))
            continue
        if content.matches(expected):
            continue
        if content.header is None:
            # 先頭の記述が無く、手で書いたファイルでもない (空白と BOM だけの) ファイル。YAML の修正は要らない
            problems.append(Problem("a", relative, f"生成したファイルの中身が無い。{header.command} を実行する"))
            continue
        actual = content.text
        if actual == expected:
            # 読んだ内容は同じで、BOM か UTF-8 として読めないバイトだけが違う。YAML の修正は要らない
            problems.append(
                Problem(
                    "a", relative,
                    f"生成し直した内容と違う (BOM か、UTF-8 として読めないバイトがある)。{header.command} を実行する",
                )
            )
            continue
        diff = "".join(
            difflib.unified_diff(
                actual.splitlines(keepends=True),
                expected.splitlines(keepends=True),
                fromfile=f"{relative} (今のファイル)",
                tofile=f"{relative} (生成し直した内容)",
            )
        )
        problems.append(Problem("a", relative, f"生成し直した内容と違う。{how}", detail=diff))
    for relative, header in generated_files(root).items():
        if relative in outputs:
            continue
        if header.source and not (root / header.source).exists():
            message = f"生成元 {header.source} が無い。このファイルを消すか、生成元を戻す"
        else:
            command = header.command or generated_header.GENERATE_COMMAND
            message = f"生成し直すと消えるファイルが残っている。{command} を実行して消す"
        problems.append(Problem("a", relative, message))
    return problems


def run_checks(root: Path, checks: tuple[str, ...]) -> CheckResult:
    result = CheckResult(checks=checks)
    if not checks:
        return result
    project, yaml_problems = load_project(root)
    if "h" in checks:
        result.problems += yaml_problems
    if "b" in checks or "k" in checks or "i" in checks or "c-2" in checks:
        # ドメインの一覧はディレクトリ名から作るので、YAML に誤りがあっても手書きの Markdown を見つけられる
        index, document_problems = load_documents(root, project)
    if "k" in checks:
        result.problems += check_length(index)
    if yaml_problems:
        result.skipped = [c for c in checks if c in ("a", "b", "c-2", "i")]
        return result
    if "b" in checks:
        result.problems += document_problems + check_links(index)
    if "i" in checks:
        result.problems += check_direction(project) + check_markdown_direction(index)
    if "c-2" in checks:
        result.problems += check_cycles(index)
    if "a" in checks:
        result.problems += check_generated(root, project)
    return result
"""検査 i (参照の向き)。

YAML の参照 (属性の refers_to) は、参照する YAML のディレクトリの祖先のディレクトリにある YAML の定義を指さない。
同じディレクトリ・子孫のディレクトリ・別のサブツリー・ほかのドメインは指してよい。判定は参照先の定義を書いた場所で行う。
違反したときの直し方は、参照される定義をサブディレクトリの YAML に移すこと (参照しているファイルを移すことではない)。

手書きの Markdown のリンクは、祖先のディレクトリの手書きのファイルを指さない。判定は参照先のアンカーのあるファイルの場所で行う。
生成したファイルを指すリンクは対象にしない (生成したファイルの場所はツールが決め、参照される定義を移して直せないため。
決めた経緯は Issue #198 のコメントの 1)。参照先のアンカーが無いリンクは、検査 b が報告するので数えない。
規則の SSOT はプラグインの規則の文書 (ファイル doc-structured/rules/doc-structured-docs.md と
doc-structured/rules/doc-structured-domains.md)。
"""

from pathlib import PurePosixPath

from .documents import Index
from .domains import Project
from .links import resolve
from .problems import Problem
from .references import all_references


def _is_ancestor(target_dir: PurePosixPath, source_dir: PurePosixPath) -> bool:
    return target_dir != source_dir and target_dir in source_dir.parents


def check_direction(project: Project) -> list[Problem]:
    problems: list[Problem] = []
    for domain in project.domains:
        for entry in domain.entries():
            if entry.refers_to is None or entry.refers_to not in project.entries:
                continue  # 参照先が無いことは検査 h が報告する
            target = project.entries[entry.refers_to]
            source_dir = PurePosixPath(entry.path).parent
            target_dir = PurePosixPath(target.path).parent
            if _is_ancestor(target_dir, source_dir):
                problems.append(
                    Problem(
                        "i",
                        entry.path,
                        f"refers_to の参照先 {target.id} は、祖先のディレクトリの {target.path} にある。"
                        f"参照される定義 ({target.id}) を、参照するファイルと同じディレクトリかその下に移す",
                        entry.refers_to_line,
                        entry.refers_to_column,
                    )
                )
    return problems


def check_markdown_direction(index: Index) -> list[Problem]:
    problems: list[Problem] = []
    for reference in all_references(index):
        if not reference.in_body:
            continue  # 本文で使われていない定義の行は、検査 b が報告する
        target = resolve(reference.file, reference.definition, index).target
        if target is None or index.file(target.path) is None:
            continue  # 参照先が無いものは検査 b が報告する。生成したファイルは対象にしない
        source_dir = PurePosixPath(reference.path).parent
        target_dir = PurePosixPath(target.path).parent
        if _is_ancestor(target_dir, source_dir):
            problems.append(
                Problem(
                    "i",
                    reference.path,
                    f"リンク {reference.written} の参照先 {target.id} は、祖先のディレクトリの手書きのファイル {target.path} にある。"
                    "参照される内容を、サブディレクトリの子のファイルに移す",
                    reference.line,
                    reference.column,
                )
            )
    return problems

"""手書きの Markdown と、リンクの参照先の一覧。

ドメインのディレクトリの下の手書きの Markdown を見つけ、すべての Markdown (生成したファイルを含む) のアンカーから、
リンクの参照先の一覧を作る。形式の SSOT はプラグインの規則の文書 (ファイル doc-structured/rules/doc-structured-docs.md と
doc-structured/rules/doc-structured-domains.md)。要点:
  - 手書きのファイルは、ドメインのディレクトリの直下の concept.md・problem.md・design.md と、
    その種類と同じ名前のサブディレクトリの <名前>.md (子のファイル。1 階層だけ)
  - ほかの名前・場所の .md は、検査 b のエラーにする
  - 参照先のアンカーは、今のファイルの内容から読む (生成したファイルが古いことは検査 a が報告する)。YAML から決まる参照先
    (ドメイン・定義・生成したファイル) のファイルは、生成する側の対応で決め、そのファイルにアンカーがあるときだけ参照先にする
  - 参照先のラベルの候補は、ID・名前・書ける形 (「種類 + 名前」に、親を直近から 0 個以上足した形。略称のある種類は、
    略称で書いた形も含む)
