// 合図の種類。order-created は注文を受け付けた、order-items-changed は注文明細の状態か数量を変えた、
// checkout-requested は会計の依頼が注文ステータス画面の一覧に出た
export const REALTIME_EVENT_TYPES = [
	'order-created',
	'order-items-changed',
	'checkout-requested'
] as const;
export type RealtimeEventType = (typeof REALTIME_EVENT_TYPES)[number];
export type RealtimeEvent = { type: RealtimeEventType };

// 接続を確かめるメッセージ。画面が PING を送り、StoreHub が PONG を返す
export const PING = 'ping';
export const PONG = 'pong';

// 合図の形を検査する。{ type: <種類> } の形でなければ (ほかの項目を持つものを含む) null
export function parseRealtimeEvent(value: unknown): RealtimeEvent | null {
	// 項目が type の 1 つだけで、その値が知っている種類であること (配列は type を持たないので、ここで断る)
	if (typeof value !== 'object' || value === null || Object.keys(value).length !== 1) return null;
	const type = REALTIME_EVENT_TYPES.find((known) => known === (value as { type?: unknown }).type);
	return type === undefined ? null : { type };
}

// WebSocket のメッセージ (JSON の文字列) を、合図として読む。JSON でなければ (PONG を含む) null
export function parseRealtimeMessage(data: string): RealtimeEvent | null {
	try {
		return parseRealtimeEvent(JSON.parse(data));
	} catch {
		return null;
	}
}

